# ===== Result Enums =====
class RtkResult(IntEnum):
    """Possible results returned for rtk requests."""

    UNKNOWN = 0
    SUCCESS = 1
    TOO_LONG = 2
    NO_SYSTEM = 5
    CONNECTION_ERROR = 6


class RtkError(MavsdkError):
    """Raised when a Rtk request fails.

    Attributes
    ----------
    result : RtkResult
        The result the request failed with.
    origin : str
        The method that failed.
    params : tuple
        The arguments the method was called with.
    """

    def __init__(self, result, origin, *params):
        super().__init__(result, origin, *params)
        self.result = result
        self.origin = origin
        self.params = params

    def __str__(self):
        return f"{self.result.name}; origin: {self.origin}; params: {self.params}"


